// ============================================================
// 🐍 贪吃蛇游戏 - 前端逻辑 (game.js)
// ============================================================

// ---------- DOM 引用 ----------
const menuScreen = document.getElementById('menuScreen');
const gameScreen = document.getElementById('gameScreen');
const gameOverScreen = document.getElementById('gameOverScreen');
const scoresScreen = document.getElementById('scoresScreen');

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const playerNameInput = document.getElementById('playerName');
const difficultySelect = document.getElementById('difficultySelect');
const scoreDisplay = document.getElementById('scoreDisplay');
const lengthDisplay = document.getElementById('lengthDisplay');
const diffDisplay = document.getElementById('diffDisplay');
const finalScore = document.getElementById('finalScore');
const finalLength = document.getElementById('finalLength');
const scoresBody = document.getElementById('scoresBody');

const startBtn = document.getElementById('startBtn');
const scoresBtn = document.getElementById('scoresBtn');
const pauseBtn = document.getElementById('pauseBtn');
const quitBtn = document.getElementById('quitBtn');
const restartBtn = document.getElementById('restartBtn');
const menuBtn = document.getElementById('menuBtn');
const backBtn = document.getElementById('backBtn');

// ---------- 游戏配置 ----------
const GRID_SIZE = 20;          // 20x20 网格
const CELL_SIZE = canvas.width / GRID_SIZE;

const DIFFICULTY = {
  easy:   { speed: 180, label: '简单' },
  normal: { speed: 120, label: '普通' },
  hard:   { speed: 70,  label: '困难' },
};

// ---------- 游戏状态 ----------
let snake = [];
let food = {};
let direction = 'right';
let nextDirection = 'right';
let score = 0;
let gameRunning = false;
let gamePaused = false;
let gameLoop = null;
let difficulty = 'normal';
let playerName = '玩家';

// ---------- 初始化 ----------
function initGame() {
  // 蛇：初始长度3，水平放置
  snake = [
    { x: 9, y: 10 },
    { x: 8, y: 10 },
    { x: 7, y: 10 },
  ];
  direction = 'right';
  nextDirection = 'right';
  score = 0;
  gamePaused = false;
  spawnFood();
  updateUI();
  draw();
}

function spawnFood() {
  let pos;
  do {
    pos = {
      x: Math.floor(Math.random() * GRID_SIZE),
      y: Math.floor(Math.random() * GRID_SIZE),
    };
  } while (snake.some(s => s.x === pos.x && s.y === pos.y));
  food = pos;
}

// ---------- 游戏循环 ----------
function startGameLoop() {
  if (gameLoop) clearInterval(gameLoop);
  const speed = DIFFICULTY[difficulty].speed;
  gameLoop = setInterval(() => {
    if (!gamePaused && gameRunning) {
      update();
      draw();
    }
  }, speed);
}

function stopGameLoop() {
  if (gameLoop) {
    clearInterval(gameLoop);
    gameLoop = null;
  }
}

// ---------- 更新逻辑 ----------
function update() {
  direction = nextDirection;

  // 计算新头部
  const head = snake[0];
  let newHead = { ...head };
  switch (direction) {
    case 'up':    newHead.y--; break;
    case 'down':  newHead.y++; break;
    case 'left':  newHead.x--; break;
    case 'right': newHead.x++; break;
  }

  // 检测是否吃到食物
  const ate = (newHead.x === food.x && newHead.y === food.y);

  // 插入新头部
  snake.unshift(newHead);
  if (!ate) {
    snake.pop(); // 没吃到就移除尾部
  } else {
    score += 10;
    spawnFood();
    updateUI();
  }

  // 碰撞检测
  const headCollision = (
    newHead.x < 0 || newHead.x >= GRID_SIZE ||
    newHead.y < 0 || newHead.y >= GRID_SIZE ||
    snake.slice(1).some(s => s.x === newHead.x && s.y === newHead.y)
  );

  if (headCollision) {
    gameOver();
    return;
  }

  updateUI();
}

// ---------- 游戏结束 ----------
function gameOver() {
  gameRunning = false;
  stopGameLoop();
  finalScore.textContent = score;
  finalLength.textContent = snake.length;
  gameScreen.style.display = 'none';
  gameOverScreen.style.display = 'block';

  // 保存分数到 SQLite
  saveScore(playerName, score, snake.length, difficulty);
}

// ---------- 保存分数 (API) ----------
async function saveScore(name, scoreVal, lengthVal, diff) {
  try {
    const res = await fetch('/api/scores', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        player_name: name,
        score: scoreVal,
        snake_length: lengthVal,
        difficulty: diff,
      }),
    });
    const data = await res.json();
    console.log('分数已保存:', data);
  } catch (err) {
    console.error('保存分数失败:', err);
  }
}

// ---------- 获取高分榜 ----------
async function loadScores() {
  try {
    const res = await fetch('/api/scores');
    const scores = await res.json();
    renderScores(scores);
  } catch (err) {
    console.error('加载高分榜失败:', err);
    scoresBody.innerHTML = '<tr><td colspan="6">加载失败，请检查后端服务</td></tr>';
  }
}

function renderScores(scores) {
  if (!scores || scores.length === 0) {
    scoresBody.innerHTML = '<tr><td colspan="6">暂无记录</td></tr>';
    return;
  }
  const diffMap = { easy: '简单', normal: '普通', hard: '困难' };
  scoresBody.innerHTML = scores.map((s, i) => {
    const rankClass = i < 3 ? `rank-${i + 1}` : '';
    const time = s.achieved_at ? new Date(s.achieved_at).toLocaleString('zh-CN') : '';
    return `<tr class="${rankClass}">
      <td>${i + 1}</td>
      <td>${escapeHtml(s.player_name)}</td>
      <td>${s.score}</td>
      <td>${s.snake_length}</td>
      <td>${diffMap[s.difficulty] || s.difficulty}</td>
      <td>${time}</td>
    </tr>`;
  }).join('');
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// ---------- 绘制 ----------
function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // 绘制网格
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.04)';
  ctx.lineWidth = 0.5;
  for (let i = 0; i <= GRID_SIZE; i++) {
    ctx.beginPath();
    ctx.moveTo(i * CELL_SIZE, 0);
    ctx.lineTo(i * CELL_SIZE, canvas.height);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * CELL_SIZE);
    ctx.lineTo(canvas.width, i * CELL_SIZE);
    ctx.stroke();
  }

  // 绘制蛇
  snake.forEach((seg, i) => {
    const x = seg.x * CELL_SIZE;
    const y = seg.y * CELL_SIZE;
    const padding = 1;
    const radius = 4;

    if (i === 0) {
      // 蛇头
      ctx.fillStyle = '#4ade80';
      ctx.shadowColor = '#4ade80';
      ctx.shadowBlur = 12;
    } else {
      // 蛇身：渐变
      const ratio = 1 - (i / snake.length) * 0.5;
      const g = Math.floor(222 * ratio);
      ctx.fillStyle = `rgb(74, ${g}, 128)`;
      ctx.shadowBlur = 0;
    }

    ctx.beginPath();
    ctx.roundRect(x + padding, y + padding, CELL_SIZE - padding * 2, CELL_SIZE - padding * 2, radius);
    ctx.fill();
  });
  ctx.shadowBlur = 0;

  // 绘制食物
  const fx = food.x * CELL_SIZE;
  const fy = food.y * CELL_SIZE;
  const cx = fx + CELL_SIZE / 2;
  const cy = fy + CELL_SIZE / 2;
  const radius = CELL_SIZE / 2 - 2;

  // 发光效果
  ctx.shadowColor = '#f43f5e';
  ctx.shadowBlur = 20;
  ctx.fillStyle = '#f43f5e';
  ctx.beginPath();
  ctx.arc(cx, cy, radius, 0, Math.PI * 2);
  ctx.fill();

  // 内圈高光
  ctx.shadowBlur = 0;
  ctx.fillStyle = '#fb7185';
  ctx.beginPath();
  ctx.arc(cx - 2, cy - 2, radius * 0.5, 0, Math.PI * 2);
  ctx.fill();

  // 暂停提示
  if (gamePaused && gameRunning) {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 32px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('⏸ 暂停中', canvas.width / 2, canvas.height / 2);
  }
}

// Canvas roundRect 辅助
CanvasRenderingContext2D.prototype.roundRect = function (x, y, w, h, r) {
  if (w < 2 * r) r = w / 2;
  if (h < 2 * r) r = h / 2;
  this.moveTo(x + r, y);
  this.lineTo(x + w - r, y);
  this.quadraticCurveTo(x + w, y, x + w, y + r);
  this.lineTo(x + w, y + h - r);
  this.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  this.lineTo(x + r, y + h);
  this.quadraticCurveTo(x, y + h, x, y + h - r);
  this.lineTo(x, y + r);
  this.quadraticCurveTo(x, y, x + r, y);
  this.closePath();
  return this;
};

// ---------- UI 更新 ----------
function updateUI() {
  scoreDisplay.textContent = score;
  lengthDisplay.textContent = snake.length;
}

// ---------- 键盘控制 ----------
function handleKeydown(e) {
  const key = e.key;
  const keyMap = {
    ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
    w: 'up', W: 'up', s: 'down', S: 'down', a: 'left', A: 'left', d: 'right', D: 'right',
  };

  const dir = keyMap[key];
  if (!dir) return;
  e.preventDefault();

  // 不允许反向
  const opposites = { up: 'down', down: 'up', left: 'right', right: 'left' };
  if (dir === opposites[direction]) return;

  nextDirection = dir;
}

// ---------- 屏幕切换 ----------
function showScreen(screen) {
  [menuScreen, gameScreen, gameOverScreen, scoresScreen].forEach(s => {
    s.style.display = 'none';
  });
  screen.style.display = 'block';
}

// ---------- 开始游戏 ----------
function startGame() {
  playerName = playerNameInput.value.trim() || '玩家';
  difficulty = difficultySelect.value;
  diffDisplay.textContent = DIFFICULTY[difficulty].label;

  initGame();
  gameRunning = true;
  showScreen(gameScreen);
  startGameLoop();
}

// ---------- 事件绑定 ----------
startBtn.addEventListener('click', startGame);

scoresBtn.addEventListener('click', () => {
  showScreen(scoresScreen);
  loadScores();
});

backBtn.addEventListener('click', () => {
  showScreen(menuScreen);
});

pauseBtn.addEventListener('click', () => {
  if (!gameRunning) return;
  gamePaused = !gamePaused;
  pauseBtn.textContent = gamePaused ? '继续' : '暂停';
  draw();
});

quitBtn.addEventListener('click', () => {
  stopGameLoop();
  gameRunning = false;
  showScreen(menuScreen);
});

restartBtn.addEventListener('click', () => {
  gameOverScreen.style.display = 'none';
  startGame();
});

menuBtn.addEventListener('click', () => {
  showScreen(menuScreen);
});

// 键盘事件
document.addEventListener('keydown', handleKeydown);

// 移动端方向按钮
document.querySelectorAll('.dir-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const dir = btn.dataset.dir;
    const opposites = { up: 'down', down: 'up', left: 'right', right: 'left' };
    if (dir === opposites[direction]) return;
    nextDirection = dir;
  });
  // 触摸事件防止滚动
  btn.addEventListener('touchstart', (e) => {
    e.preventDefault();
    const dir = btn.dataset.dir;
    const opposites = { up: 'down', down: 'up', left: 'right', right: 'left' };
    if (dir === opposites[direction]) return;
    nextDirection = dir;
  });
});

// 空格键暂停
document.addEventListener('keydown', (e) => {
  if (e.key === ' ' && gameRunning) {
    e.preventDefault();
    pauseBtn.click();
  }
});

// 防止页面方向键滚动
window.addEventListener('keydown', (e) => {
  if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(e.key)) {
    e.preventDefault();
  }
});

// ---------- 初始显示 ----------
showScreen(menuScreen);

